let myCanvas;
let currentAlgorithmIndex = -1;
let algorithms = [];
let paramsHistory = [];
let currentParamIndex = -1;

let zoomFactor = 1.0;
let panX = 0.0;
let panY = 0.0;
let probSetIndex = 0;
let paramArray = [0,0,0];
const buttonLabels = [
  "New Algorithm","New Params","Prev Alg","Prev Params","Capture",
  "Prob Set","ColorPerm","Warp/Invert","Zoom +","Zoom -",
  "Pan Up","Pan Down","Pan Left","Pan Right"
];

let aaEnabled = true;
let aaLevel = 2;
const MAX_PIXEL_DENSITY = 4;

let animationSpeed = 1.0;

let uiContainer, uiHeader, uiContent;
let aaCheckbox, aaLevelDropdown;
let isDragging = false;
let dragOffsetX = 0;
let dragOffsetY = 0;

let upPressed = false;
let downPressed = false;
let leftPressed = false;
let rightPressed = false;
let panVelX = 0;
let panVelY = 0;
const PAN_ACCEL = 2.0;
const PAN_DAMP = 0.8;
let zoomVel = 0;
const ZOOM_DAMP = 0.85;

const MAX_DEPTH = 40;

let fractalMode = 0;
let fractalMode2 = 0;

function setup() {
  pixelDensity(1);
  initCanvas();
  newAlgorithm();
  newParameters();
  createUI();
}

function initCanvas() {
  if (myCanvas) myCanvas.remove();
  if (aaEnabled) {
    aaLevel = constrain(aaLevel, 1, MAX_PIXEL_DENSITY);
    pixelDensity(aaLevel);
  } else {
    aaLevel = 1;
    pixelDensity(1);
  }
  myCanvas = createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();

  for (let i = 0; i < algorithms.length; i++) {
    let fragSource = algorithms[i].fragSource;
    let vertCode = `
      attribute vec3 aPosition;
      void main(){
        gl_Position = vec4(aPosition,1.0);
      }
    `;
    let s = createShader(vertCode, fragSource);
    algorithms[i].shaderObj = s;
  }
}

function draw() {
  if (upPressed) panVelY -= PAN_ACCEL;
  if (downPressed) panVelY += PAN_ACCEL;
  if (leftPressed) panVelX += PAN_ACCEL;
  if (rightPressed) panVelX -= PAN_ACCEL;

  panX += panVelX;
  panY += panVelY;
  panVelX *= PAN_DAMP;
  panVelY *= PAN_DAMP;

  zoomFactor *= (1 + zoomVel);
  zoomFactor = max(0.00001, zoomFactor);
  zoomVel *= ZOOM_DAMP;

  background(0);
  let algo = algorithms[currentAlgorithmIndex];
  if (algo && algo.shaderObj) {
    shader(algo.shaderObj);
    setUniforms(algo.shaderObj);
    beginShape(TRIANGLES);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, -1, 0, 1, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, 1, 0, 0, 1);
    endShape();
    resetShader();
  }
}

function windowResized(){
  initCanvas();
}

function mouseDragged(){
  if(isDragging){
    uiContainer.position((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - dragOffsetX, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - dragOffsetY);
  }
}

function mouseReleased(){
  isDragging = false;
}

function startDrag() {
  isDragging = true;
  let pos = uiContainer.position();
  dragOffsetX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - pos.x;
  dragOffsetY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - pos.y;
}

function endDrag(){
  isDragging = false;
}

function mouseWheel(event) {
  if (event.delta < 0) {
    zoomVel -= 0.02;
  } else {
    zoomVel += 0.02;
  }
  return false;
}

function keyPressed() {
  if (key === 'N' || key === 'n') {
    handleButton("New Algorithm");
  } else if (key === 'M' || key === 'm') {
    handleButton("New Params");
  } else if (key === 'C' || key === 'c') {
    handleButton("Capture");
  }

  if (keyCode === LEFT_ARROW) leftPressed = true;
  if (keyCode === RIGHT_ARROW) rightPressed = true;
  if (keyCode === UP_ARROW) upPressed = true;
  if (keyCode === DOWN_ARROW) downPressed = true;
}

function keyReleased() {
  if (keyCode === LEFT_ARROW) leftPressed = false;
  if (keyCode === RIGHT_ARROW) rightPressed = false;
  if (keyCode === UP_ARROW) upPressed = false;
  if (keyCode === DOWN_ARROW) downPressed = false;
}

function newAlgorithm(){
  currentAlgorithmIndex++;
  algorithms.splice(currentAlgorithmIndex);
  let nodeCount = floor(random(20, 40));
  let fragCode = buildFragCode(nodeCount);
  var vertCode = `
    attribute vec3 aPosition;
    void main(){
      gl_Position = vec4(aPosition,1.0);
    }
  `;
  var s = createShader(vertCode, fragCode);
  algorithms.push({fragSource:fragCode, shaderObj:s});
  currentParamIndex = -1;
  paramsHistory = [];
}

function newParameters(){
  if(currentAlgorithmIndex < 0) return;
  currentParamIndex++;
  paramsHistory.splice(currentParamIndex);
  paramsHistory.push([random(1), random(1), random(1)]);

  fractalMode = floor(random(23));
  fractalMode2 = floor(random(23));
}

function prevAlgorithm(){
  if(currentAlgorithmIndex>0) currentAlgorithmIndex--;
}

function prevParams(){
  if(currentParamIndex>0) currentParamIndex--;
}

function getCurrentParams(){
  if(currentParamIndex<0 || currentParamIndex>=paramsHistory.length) return [0,0,0];
  return paramsHistory[currentParamIndex];
}

function handleButton(label){
  switch(label){
    case "New Algorithm":
      newAlgorithm();
      newParameters();
      break;
    case "New Params":
      newParameters();
      break;
    case "Prev Alg":
      prevAlgorithm();
      break;
    case "Prev Params":
      prevParams();
      break;
    case "Capture":
      saveCanvas("capture_" + nf(millis(),1,0), "png");
      break;
    case "Prob Set":
      probSetIndex = (probSetIndex + 1) % 3;
      break;
    case "ColorPerm":
      applyColorPermutation();
      break;
    case "Warp/Invert":
      applyWarpOrInvert();
      break;
    case "Zoom +":
      zoomFactor *= 1.1;
      break;
    case "Zoom -":
      zoomFactor /= 1.1;
      break;
    case "Pan Up":
      panY -= 40;
      break;
    case "Pan Down":
      panY += 40;
      break;
    case "Pan Left":
      panX -= 40;
      break;
    case "Pan Right":
      panX += 40;
      break;
  }
}

function handleAAChange() {
  aaEnabled = aaCheckbox.checked();
  if (aaEnabled) {
    aaLevelDropdown.removeAttribute('disabled');
    let selectedVal = aaLevelDropdown.value();
    aaLevel = parseInt(selectedVal);
    aaLevel = constrain(aaLevel, 1, MAX_PIXEL_DENSITY);
  } else {
    aaLevelDropdown.attribute('disabled', '');
    aaLevel = 1;
  }
  initCanvas();
}

function applyColorPermutation(){
  var algo = algorithms[currentAlgorithmIndex];
  if(!algo) return;
  let newFrag = algo.fragSource.replace(
    "gl_FragColor = vec4(finalColor, 1.0);",
    "gl_FragColor = vec4(finalColor.gbr, 1.0);"
  );
  let vtx = `
    attribute vec3 aPosition;
    void main(){ gl_Position = vec4(aPosition,1.0); }
  `;
  var s = createShader(vtx, newFrag);
  algo.shaderObj = s;
  algo.fragSource = newFrag;
}

function applyWarpOrInvert(){
  var algo = algorithms[currentAlgorithmIndex];
  if(!algo)return;
  let r = random();
  let replacement = (r<0.5)
    ? "finalColor = 1.0 - finalColor;"
    : "finalColor = fract(finalColor + 0.5);";
  var newFrag = algo.fragSource.replace(
    "//POSTPROCESS_PLACEHOLDER",
    replacement + " //POSTPROCESS_PLACEHOLDER"
  );
  var vtx = `
    attribute vec3 aPosition;
    void main(){ gl_Position = vec4(aPosition,1.0); }
  `;
  var s = createShader(vtx, newFrag);
  algo.shaderObj = s;
  algo.fragSource = newFrag;
}

const unaryOps = ["sin","cos","tan","abs","sqrt","log"];

function pickRandom(arr) {
  return arr[floor(random(arr.length))];
}

function clamp01(expr) {
  return "fract(" + expr + ")";
}

function buildExpression(nodesLeft, depth){
  if(nodesLeft < 1 || depth > MAX_DEPTH) {
    return randomLeaf();
  }
  if(random() < 0.2 && depth > 0) {
    return randomLeaf();
  }
  let dice = random();
  if(dice < 0.3) {
    let op = pickRandom(unaryOps);
    let sub = buildExpression(nodesLeft-1, depth+1);
    if(op === "sqrt"){
      return "sqrt(max(0.0, " + sub + "))";
    } else if(op === "log"){
      return "log(abs(" + sub + ") + 0.0001)";
    } else {
      return op + "(" + sub + ")";
    }
  } else if(dice < 0.6) {
    let specialOps = ["fold01","fractOp","noiseOp"];
    var op = pickRandom(specialOps);
    if(op === "fold01"){
      var sub = buildExpression(nodesLeft-1, depth+1);
      return "fold01(" + sub + ")";
    } else if(op === "fractOp"){
      var sub = buildExpression(nodesLeft-1, depth+1);
      return "fract(" + sub + ")";
    } else {
      let sx = buildExpression(floor((nodesLeft-1)/2), depth+1);
      let sy = buildExpression(floor((nodesLeft-1)/2), depth+1);
      return "noise2D(vec2(" + sx + "," + sy + "))";
    }
  } else if(dice < 0.9) {
    let binOps = ["+","-","*","/","min","max"];
    var op = pickRandom(binOps);
    let left = buildExpression(nodesLeft-1, depth+1);
    let right = buildExpression(nodesLeft-1, depth+1);
    if(op === "/") {
      return "(safeDiv((" + left + "),(" + right + ")))";
    } else if(op === "min" || op === "max"){
      return op + "(" + left + "," + right + ")";
    } else {
      return "(" + left + ")" + op + "(" + right + ")";
    }
  } else {
    let a = buildExpression(nodesLeft-1, depth+1);
    let b = buildExpression(nodesLeft-1, depth+1);
    let t = buildExpression(nodesLeft-1, depth+1);
    return "mix(" + a + "," + b + "," + clamp01(t) + ")";
  }
}

function randomLeaf(){
  var r = floor(random(14));
  switch(r){
    case 0: return "x";
    case 1: return "y";
    case 2: return "u_time";
    case 3: return "u_params[0]";
    case 4: return "u_params[1]";
    case 5: return "u_params[2]";
    case 6: return "sqrt(x*x + y*y)";
    case 7: return "atan(y,x)";
    case 8: return "noise2D(vec2(x,y))";
    case 9: return "noise2D(vec2(u_time, x-y))";
    case 10: return "(length(vec2(x,y))*sin(u_time))";
    case 11: return "(0.5 + 0.5*sin(x*3.1415 + y*3.1415))";
    case 12: return "(abs(sin(x*5.0)*cos(y*5.0)))";
    default:
      return nf(random(-1,1),1,3);
  }
}

function buildCoordTransformSnippet(){
  let transformCount = floor(random(1,3));
  let snippet = "vec2 coord = uv;\nuv = coord;\n";
  let possible = [
    "swirl","reflect","tile","kaleido","moebius","invert","wave",
    "twirl","sphere","ripple","pinch","bulge","fisheye"
  ];
  for(let i=0; i<transformCount; i++){
    let choice = possible[floor(random(possible.length))];
    if(choice==="swirl"){
      let amt = nf(random(-2.0,2.0),1,3);
      snippet += `uv = swirlCoord(uv, float(${amt}) + 0.3*sin(u_time*0.2));\n`;
    } else if(choice==="reflect"){
      let freq = nf(random(1.0,6.0),1,3);
      snippet += `uv = reflectCoord(uv, float(${freq}) + 0.3*sin(u_time*0.2));\n`;
    } else if(choice==="tile"){
      let scale = nf(random(1.0,5.0),1,3);
      snippet += `uv = tileCoord(uv, float(${scale}) + 0.3*sin(u_time*0.2));\n`;
    } else if(choice==="kaleido"){
      let seg = nf(random(3.0,10.0),1,3);
      snippet += `uv = kaleidoCoord(uv, float(${seg}) + 0.3*sin(u_time*0.2));\n`;
    } else if(choice==="moebius"){
      var a = nf(random(-1.0,1.0),1,3);
      snippet += `uv = moebiusCoord(uv, float(${a}) + 0.3*sin(u_time*0.2));\n`;
    } else if(choice==="invert"){
      snippet += `uv = invertCoord(uv);\n`;
    } else if(choice==="wave"){
      var freq = nf(random(1.0,5.0),1,3);
      let amp = nf(random(0.1,0.5),1,3);
      snippet += `uv = waveCoord(uv, float(${freq}) + 0.3*sin(u_time*0.2), float(${amp}) + 0.1*cos(u_time*0.2));\n`;
    } else if(choice==="twirl"){
      let angle = nf(random(-3.14,3.14),1,3);
      let radius = nf(random(0.2,2.0),1,3);
      snippet += `uv = twirlCoord(uv, float(${angle}) + 0.3*sin(u_time*0.2), float(${radius}));\n`;
    } else if(choice==="sphere"){
      snippet += `uv = sphereCoord(uv) + 0.001*sin(u_time*1.0);\n`;
    } else if(choice==="ripple"){
      var freq = nf(random(2.0,8.0),1,3);
      var amp = nf(random(0.05,0.3),1,3);
      snippet += `uv = rippleCoord(uv, float(${freq}) + 0.3*sin(u_time*0.2), float(${amp}) + 0.1*cos(u_time*0.2));\n`;
    } else if(choice==="pinch"){
      let strength = nf(random(0.5,2.0),1,3);
      snippet += `uv = pinchCoord(uv, float(${strength}) + 0.3*sin(u_time*0.2));\n`;
    } else if(choice==="bulge"){
      var strength = nf(random(0.5,1.5),1,3);
      let rad = nf(random(0.5,2.0),1,3);
      snippet += `uv = bulgeCoord(uv, float(${strength}) + 0.3*sin(u_time*0.2), float(${rad}));\n`;
    } else if(choice==="fisheye"){
      let power = nf(random(0.5,2.0),1,3);
      snippet += `uv = fisheyeCoord(uv, float(${power}) + 0.3*sin(u_time*0.2));\n`;
    }
  }
  snippet += `uv = rotate2D(uv, 0.02*u_time);\n`;
  return snippet;
}

function buildFragCode(nodeCount){
  let eR = buildExpression(nodeCount,0);
  let eG = buildExpression(nodeCount,0);
  let eB = buildExpression(nodeCount,0);

  let fractalSnippet = buildFractalSnippet();
  let coordTransforms = buildCoordTransformSnippet();

  let postProcesses = [
    "finalColor = fract(finalColor);",
    "finalColor = pow(finalColor, vec3(0.8));",
    "finalColor = 0.7 + 0.3*sin(finalColor * 3.14159 * 2.0);",
    "finalColor = finalColor * (1.0 - length(uv)*0.2);"
  ];
  let chosenPP = postProcesses[floor(random(postProcesses.length))];

  return `
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 u_resolution;
uniform float u_zoom;
uniform vec2 u_pan;
uniform float u_time;
uniform float u_params[3];
uniform float u_fractalMode;
uniform float u_fractalMode2;

float safeDiv(float a, float b){
  return (abs(b) < 1e-6) ? 0.0 : (a/b);
}
float fold01(float v){
  v = abs(mod(v, 2.0));
  if(v > 1.0) v = 2.0 - v;
  return v;
}
float hash12(vec2 p) {
  vec3 p3  = fract(vec3(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 19.19);
  return fract((p3.x + p3.y) * p3.z);
}
vec2 hash2(vec2 p){
  float n = sin(dot(p, vec2(7.0,157.0)));
  return fract(vec2(2097152.0,262144.0)*n);
}
float noise2D(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash12(i + vec2(0.0,0.0));
  float b = hash12(i + vec2(1.0,0.0));
  float c = hash12(i + vec2(0.0,1.0));
  float d = hash12(i + vec2(1.0,1.0));
  vec2 u = f*f*(3.0-2.0*f);
  return mix(a, b, u.x) +
         (c - a)* u.y * (1.0 - u.x) +
         (d - b)* u.x * u.y;
}
vec2 swirlCoord(vec2 uv, float amount){
  float r = length(uv);
  float theta = atan(uv.y, uv.x);
  theta += amount * r;
  return vec2(r*cos(theta), r*sin(theta));
}
vec2 reflectCoord(vec2 uv, float freq){
  return abs(mod(uv*freq, 2.0) - 1.0);
}
vec2 tileCoord(vec2 uv, float scale){
  return mod(uv * scale, 1.0) - 0.5;
}
vec2 kaleidoCoord(vec2 z, float segCount){
  float r = length(z);
  float ang = atan(z.y, z.x);
  float seg = 6.28318530718 / segCount;
  ang = mod(ang, seg);
  return vec2(r*cos(ang), r*sin(ang));
}
vec2 moebiusCoord(vec2 z, float a){
  float denom = 1.0 + a*(z.x + z.y);
  if(abs(denom)<1e-4) denom = 1e-4;
  return z / denom;
}
vec2 invertCoord(vec2 z){
  float r2 = dot(z,z);
  if(r2 < 1e-6) r2 = 1e-6;
  return z / r2;
}
vec2 waveCoord(vec2 uv, float freq, float amp){
  return vec2(
    uv.x + sin(uv.y * freq)*amp,
    uv.y + sin(uv.x * freq)*amp
  );
}
vec2 twirlCoord(vec2 uv, float angle, float radius){
  float r = length(uv);
  float theta = atan(uv.y, uv.x);
  float factor = smoothstep(0.0, radius, r) * angle;
  theta += factor;
  return vec2(r*cos(theta), r*sin(theta));
}
vec2 sphereCoord(vec2 uv){
  float r2 = dot(uv, uv);
  float factor = 1.0 / (1.0 + r2);
  return uv * factor;
}
vec2 rippleCoord(vec2 uv, float freq, float amp){
  float r = length(uv);
  float angle = atan(uv.y, uv.x);
  float ripple = sin(r * freq) * amp;
  r += ripple;
  return vec2(r*cos(angle), r*sin(angle));
}
vec2 pinchCoord(vec2 uv, float strength){
  float r = length(uv);
  float theta = atan(uv.y, uv.x);
  r = pow(r, strength);
  return vec2(r*cos(theta), r*sin(theta));
}
vec2 bulgeCoord(vec2 uv, float strength, float rad){
  float r = length(uv);
  if(r < rad){
    float t = sin((r/rad)*1.5708)*strength;
    r = mix(r, r*t, 0.5);
  }
  float a = atan(uv.y, uv.x);
  return vec2(r*cos(a), r*sin(a));
}
vec2 fisheyeCoord(vec2 uv, float power){
  float r = length(uv) + 1e-9;
  float factor = (r + 1.0) / (r + 0.01) * power;
  uv *= factor;
  return uv;
}
vec2 rotate2D(vec2 p, float a){
  float ca = cos(a), sa = sin(a);
  return vec2(ca*p.x - sa*p.y, sa*p.x + ca*p.y);
}

${fractalSnippet}

vec3 mergeFractals(vec2 uv, float fm1, float fm2){
  vec3 c1 = fractalSelector(uv, fm1);
  vec3 c2 = fractalSelector(uv, fm2);
  return mix(c1, c2, 0.5);
}

void main(){
  vec2 uv = gl_FragCoord.xy / min(u_resolution.x, u_resolution.y);
  uv -= 0.5 * (u_resolution / min(u_resolution.x, u_resolution.y));
  uv -= (u_pan / min(u_resolution.x, u_resolution.y));
  uv *= u_zoom;

  ${coordTransforms}

  float x = uv.x;
  float y = uv.y;
  float rVal = ${eR};
  float gVal = ${eG};
  float bVal = ${eB};

  vec3 finalColor = mergeFractals(uv, u_fractalMode, u_fractalMode2);

  //POSTPROCESS_PLACEHOLDER
  ${chosenPP}

  gl_FragColor = vec4(finalColor, 1.0);
}
`;
}

function buildFractalSnippet(){
  return `
// 0 - Mandelbrot
vec3 mandelbrotColor(vec2 z){
  const int M_ITER = 128;
  vec2 c = z;
  vec2 w = vec2(0.0);
  int iCount = 0;
  for(int i=0; i<M_ITER; i++){
    if(dot(w,w) > 4.0){
      iCount = i;
      break;
    }
    w = vec2(w.x*w.x - w.y*w.y, 2.0*w.x*w.y) + c;
  }
  float v = float(iCount)/float(M_ITER);
  return vec3(v, v*v, sqrt(v));
}

// 1 - Julia
vec3 juliaColor(vec2 z){
  const int J_ITER = 128;
  vec2 c = vec2(0.355, 0.355);
  int iCount = 0;
  for(int i=0; i<J_ITER; i++){
    if(dot(z,z) > 4.0){
      iCount = i;
      break;
    }
    z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
  }
  float v = float(iCount)/float(J_ITER);
  return vec3(0.3 + 0.7*v, 0.2*v, v*v);
}

// 2 - Koch Snowflake approx
vec3 kochSnowflakeColor(vec2 uv){
  float d = 0.0;
  float scale = 3.0;
  for(int i=0; i<5; i++){
    uv = abs(mod(uv*scale,2.0)-1.0);
    scale += 0.5;
    d += length(uv-0.5)*0.1;
  }
  d = fract(d*1.5);
  return vec3(d, 1.0-d, d*0.5);
}

// 3 - Sierpinski Triangle
float sierpinski(vec2 p) {
  for(int i=0; i<8; i++){
    if(p.x*0.5 > p.y) return 0.0;
    p *= 2.0;
  }
  return 1.0;
}
vec3 sierpinskiColor(vec2 uv){
  float v = sierpinski(uv*2.0+1.0);
  return vec3(v, v, v);
}

// 4 - Barnsley Fern
vec3 barnsleyFernColor(vec2 z){
  float n = noise2D(z*10.0);
  return vec3(n, n*0.7, n*0.4);
}

// 5 - Cantor Set
float cantorDistance(float v){
  for(int i=0; i<12; i++){
    float r = mod(v*3.0,3.0);
    if(r>1.0 && r<2.0) return 0.0;
    v *= 3.0;
  }
  return 1.0;
}
vec3 cantorColor(vec2 uv){
  float val = cantorDistance((uv.x+1.0)*0.5);
  return vec3(val);
}

// 6 - 2D Flame
vec3 flameColor(vec2 uv){
  float seed = uv.x * 12.9898 + uv.y * 78.233;
  const int ITER = 20;
  vec2 z = uv * 0.5;      
  vec3 colorAccum = vec3(0.0);
  float alphaAccum = 0.0;
  for(int i = 0; i < ITER; i++){
    seed = fract(sin(seed) * 43758.5453);
    float r = seed * 4.0;
    if(r < 1.0){
      float r2 = dot(z,z) + 1e-6;
      z = z / r2;
      colorAccum += vec3(0.1, 0.4, 0.8);
    }
    else if(r < 2.0){
      float r2 = dot(z,z);
      float c = cos(r2);
      float s = sin(r2);
      z = vec2(c*z.x - s*z.y, s*z.x + c*z.y);
      colorAccum += vec3(0.8, 0.2, 0.4);
    }
    else if(r < 3.0){
      float r2 = dot(z,z) + 1e-6;
      z = vec2(
        (z.x - z.y)*(z.x + z.y)/r2,
        2.0*z.x*z.y / r2
      );
      colorAccum += vec3(0.2, 0.8, 0.3);
    }
    else {
      z = z * 0.7 + vec2(0.2, -0.2);
      colorAccum += vec3(1.0, 0.8, 0.0);
    }
    alphaAccum += 1.0;
  }
  vec3 finalColor = colorAccum / alphaAccum;
  finalColor = pow(finalColor, vec3(0.8));
  return finalColor;
}

// 7 - L-System (simplified)
vec3 lsystemColor(vec2 uv){
  const int NUM_SEG = 6;
  vec4 lineSegments[6];
  lineSegments[0] = vec4(0.0, 0.0,  0.0, 0.5);
  lineSegments[1] = vec4(0.0, 0.5,  0.2, 0.7);
  lineSegments[2] = vec4(0.0, 0.5, -0.2, 0.7);
  lineSegments[3] = vec4(0.2, 0.7,  0.3, 1.0);
  lineSegments[4] = vec4(-0.2,0.7, -0.3, 1.0);
  lineSegments[5] = vec4(0.0, 0.5,  0.0, 1.0);

  float minDist = 1000.0;
  for(int i=0; i<NUM_SEG; i++){
    vec2 p1 = lineSegments[i].xy;
    vec2 p2 = lineSegments[i].zw;
    vec2 v = p2 - p1;
    vec2 w = uv - p1;
    float t = clamp(dot(w,v)/dot(v,v), 0.0, 1.0);
    vec2 projection = p1 + t*v;
    float distLine = length(uv - projection);
    if(distLine < minDist) minDist = distLine;
  }
  float threshold = 0.02;
  float lineMask = smoothstep(threshold, threshold*0.5, minDist);
  return mix(vec3(0.1, 0.8, 0.2), vec3(0.0), lineMask);
}

// 8 - Newton Fractal
vec3 newtonFractalColor(vec2 uv){
  const int MAX_ITER = 64;
  vec2 z = uv;
  for(int i=0; i<MAX_ITER; i++){
    float r2 = dot(z,z);
    if(r2 < 1e-9) break;
    vec2 fz = vec2(z.x*z.x*z.x - 3.0*z.x*z.y*z.y - 1.0,
                   3.0*z.x*z.x*z.y - z.y*z.y*z.y);
    vec2 dfz = vec2(3.0*(z.x*z.x - z.y*z.y),
                    3.0*(2.0*z.x*z.y));
    float denom = dfz.x*dfz.x + dfz.y*dfz.y + 1e-12;
    vec2 corr = vec2(
      (fz.x*dfz.x + fz.y*dfz.y)/denom,
      (fz.y*dfz.x - fz.x*dfz.y)/denom
    );
    z = z - corr;
  }
  vec2 root1 = vec2(1.0, 0.0);
  vec2 root2 = vec2(-0.5,  0.8660254037);
  vec2 root3 = vec2(-0.5, -0.8660254037);
  float d1 = length(z - root1);
  float d2 = length(z - root2);
  float d3 = length(z - root3);
  if(d1 < d2 && d1 < d3){
    return vec3(1.0, 0.3, 0.3);
  } else if(d2 < d1 && d2 < d3){
    return vec3(0.3, 1.0, 0.3);
  } else {
    return vec3(0.3, 0.3, 1.0);
  }
}

// 9 - Lorenz
vec3 lorenzColor(vec2 uv){
  float x=0.01, y=0.0, z=0.0;
  float dt=0.01;
  float sigma=10.0, rho=28.0, beta=8.0/3.0;
  float c=0.0;
  for(int i=0; i<100; i++){
    float dx = sigma*(y - x);
    float dy = x*(rho - z) - y;
    float dz = x*y - beta*z;
    x += dx*dt;
    y += dy*dt;
    z += dz*dt;
    if(abs(uv.x - x*0.02) < 0.005 && abs(uv.y - y*0.02) < 0.005) c += 1.0;
  }
  c = clamp(c,0.0,1.0);
  return vec3(c, c*0.5, c*0.8);
}

// 10 - Rössler
vec3 rosslerColor(vec2 uv){
  float x=0.01, y=0.0, z=0.0;
  float a=0.2, b=0.2, cc=5.7;
  float dt=0.02;
  float col=0.0;
  for(int i=0; i<80; i++){
    float dx = -(y+z);
    float dy = x+a*y;
    float dz = b+z*(x-cc);
    x += dx*dt; 
    y += dy*dt; 
    z += dz*dt;
    if(abs(uv.x - x*0.03) < 0.007 && abs(uv.y - y*0.03) < 0.007) col += 1.0;
  }
  return vec3(col, 0.5*col, col*0.3);
}

// 11 - Apollonian
vec3 apollonianColor(vec2 uv){
  float t=0.0;
  vec2 p = uv*2.0;
  for(int i=0; i<5; i++){
    float r = length(p) - 1.0;
    t += step(r,0.0);
    p *= 1.5;
  }
  return vec3(fract(t), fract(t*0.5), fract(t*0.7));
}

// 12 - Pythagoras Tree
vec3 pythagorasTreeColor(vec2 uv){
  float col=0.0;
  vec2 p = uv;
  for(int i=0; i<5; i++){
    p = abs(p)*1.2 - 0.5;
    col += step(length(p), 0.5);
  }
  return vec3(col*0.2, col*0.6, col);
}

// 13 - Penrose
float penroseVal(vec2 uv){
  float angles[5];
  angles[0] = 0.0;
  angles[1] = 72.0;
  angles[2] = 144.0;
  angles[3] = 216.0;
  angles[4] = 288.0;
  float n = 0.0;
  uv *= 2.0;
  for(int i = 0; i < 5; i++){
    float a = radians(angles[i]);
    float d = uv.x * cos(a) + uv.y * sin(a);
    n += cos(d * 1.61803);
  }
  float c = (n + 5.0) / (2.0 * 5.0);
  return fract(c);
}
vec3 penroseColor(vec2 uv){
  float c = penroseVal(uv);
  return vec3(c, c * 0.7, 1.0 - c);
}

// 14 - Voronoi
float voronoi(vec2 x){
  vec2 n = floor(x);
  vec2 f = fract(x);
  float res = 1.0;
  for(int j=-1;j<=1;j++){
    for(int i=-1;i<=1;i++){
      vec2 g = vec2(float(i),float(j));
      vec2 o = hash2(n+g);
      vec2 r = g + o - f;
      float d = dot(r,r);
      res = min(res, d);
    }
  }
  return sqrt(res);
}
vec3 voronoiColor(vec2 uv){
  float v = voronoi(uv*4.0);
  return vec3(v, 1.0-v, v*0.5);
}

// 15 - Mandelbulb (2D projection)
vec3 mandelbulbColor(vec2 uv){
  const int MBULB_ITER = 30;
  vec2 z = uv;
  float power = 8.0;
  float r = length(z);
  float theta = atan(z.y, z.x);
  int iCount = 0;
  for(int i=0; i<MBULB_ITER; i++){
    r = pow(r, power);
    theta *= power;
    z = vec2(r*cos(theta), r*sin(theta)) + uv;
    if(length(z) > 2.0){
      iCount = i;
      break;
    }
    r = length(z);
    theta = atan(z.y, z.x);
  }
  float val = float(iCount)/float(MBULB_ITER);
  return vec3(val, val*0.5, val*0.2);
}

// 16 - Mandelbox (2D projection)
vec3 mandelboxColor(vec2 uv){
  const int MBOX_ITER = 24;
  vec2 z = uv;
  float scale = 1.5;
  int iCount = 0;
  for(int i=0; i<MBOX_ITER; i++){
    if(z.x > 1.0) z.x = 2.0 - z.x;
    else if(z.x < -1.0) z.x = -2.0 - z.x;
    if(z.y > 1.0) z.y = 2.0 - z.y;
    else if(z.y < -1.0) z.y = -2.0 - z.y;
    z *= scale;
    z += uv;
    if(length(z) > 2.0){
      iCount = i;
      break;
    }
  }
  float val = float(iCount)/float(MBOX_ITER);
  return vec3(val*0.6, val, val*0.3);
}

// 17 - Duffing
vec3 duffingColor(vec2 uv){
  float x = 0.1;
  float y = 0.0;
  float a = 2.75;
  float b = 0.2;
  float dt = 0.02;
  float c = 0.0;
  for(int i=0; i<100; i++){
    float dx = y;
    float dy = -b*y - a*x - x*x*x;
    x += dx*dt;
    y += dy*dt;
    if(abs(uv.x - x*0.1) < 0.01 && abs(uv.y - y*0.1) < 0.01){
      c += 1.0;
    }
  }
  c = clamp(c, 0.0, 1.0);
  return vec3(c, c*0.7, c*0.4);
}

// 18 - Julia-Penrose
vec3 juliaPenroseColor(vec2 z){
  float pen = penroseVal(z * 2.0);
  const int J_ITER = 128;
  vec2 c = vec2(0.355 * pen, 0.355 * pen);
  int iCount = 0;
  for(int i=0; i<J_ITER; i++){
    if(dot(z,z) > 4.0){
      iCount = i;
      break;
    }
    z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
  }
  float v = float(iCount)/float(J_ITER);
  return vec3(0.3 + 0.7*v*pen, 0.2*v*pen, v*v + pen*0.3);
}

// 19 - Tricorn
vec3 tricornColor(vec2 uv){
  const int T_ITER = 128;
  vec2 z = vec2(0.0);
  vec2 c = uv;
  int iCount = 0;
  for(int i=0; i<T_ITER; i++){
    float x2 = z.x*z.x;
    float y2 = z.y*z.y;
    float xy = z.x*z.y;
    z = vec2(x2 - y2, -2.0*xy) + c;
    if(dot(z,z) > 4.0){
      iCount = i;
      break;
    }
  }
  float v = float(iCount)/float(T_ITER);
  return vec3(v, v*v, sqrt(v));
}

// 20 - Burning Ship
vec3 burningShipColor(vec2 uv){
  const int B_ITER = 128;
  vec2 c = uv;
  vec2 z = vec2(0.0);
  int iCount = 0;
  for(int i=0; i<B_ITER; i++){
    float zx = abs(z.x);
    float zy = abs(z.y);
    z = vec2(zx*zx - zy*zy, 2.0*zx*zy) + c;
    if(dot(z,z) > 4.0){
      iCount = i;
      break;
    }
  }
  float v = float(iCount)/float(B_ITER);
  return vec3(v, v*v, v*v*v);
}

// 21 - Henon
vec3 henonColor(vec2 uv){
  float a = 1.4;
  float b = 0.3;
  vec2 p = uv;
  vec2 z = vec2(0.0);
  float col = 0.0;
  for(int i=0; i<200; i++){
    float xNew = 1.0 - a*z.x*z.x + z.y;
    float yNew = b*z.x;
    z = vec2(xNew, yNew);
    if(distance(z, p)<0.05){
      col += 1.0;
    }
  }
  col = clamp(col, 0.0, 1.0);
  return vec3(col, 0.5*col, 1.0-col);
}

// 22 - (Placeholder)
vec3 poincareDiscColor(vec2 uv){
  float r = length(uv);
  float val = smoothstep(0.0, 1.0, 1.0 - r);
  return vec3(val, val*0.7, val*0.4);
}

vec3 fractalSelector(vec2 uv, float mode){
  int m = int(mod(mode, 23.0));
  if(m == 0) return mandelbrotColor(uv);
